<?php
/** Current public withdrawal: email lookup and typed choice, without a participant session or email link. */
function pg_email_http_request($p,$screen,$f,$email,$mode){$r=pe_http_request($screen,'withdraw');$r['email']=$email;$r['mode']=$mode;$r['expected_revision']=(int)pg_row($f)['revision'];$r['confirmation_text']=EIPSI\StudyEngine\Longitudinal\InitialScreen::withdrawalPhrase(EIPSI\StudyEngine\Longitudinal\Configuration::read($f['definition'])['initial_screen']['withdrawal'],$mode);return $r;}
pg_case('HTTP landing is read-only and private without recovering a participant',function()use(&$hp,&$hf,&$hc,&$hs,&$he){$c=EIPSI\StudyEngine\Longitudinal\InitialScreen::defaults();list($hp,$http,$hc,$he)=pf_http_enroll(null,array('initial_screen'=>$c));$hf=pf_http_frame($hp,$http,$hc);$before=pg_row($hf);$hs=pf_http($hp['public'],$hc);pe_assert($hs['status']===200&&$hs['data']['state']==='EMAIL_ENTRY'&&strpos($hs['data']['html'],'data-withdrawal-lookup="1"')!==false&&strpos($hs['headers']['cache-control'],'no-store')!==false,'No public withdrawal');pe_assert(!preg_match('/id="study-email"[^>]*value="[^"]+"/',$hs['data']['html']),'Cookie restored email');pe_equal($before,pg_row($hf));});
pg_case('HTTP CSRF rejection has no withdrawal side effect',function()use(&$hp,&$hc,&$hs,&$hf,&$he){$r=pg_email_http_request($hp,$hs,$hf,$he,'RETAIN_FOR_ANALYSIS');$r['csrf']='forged';$reply=pf_http($hp['public'],$hc,$r);pe_assert($reply['status']===403&&pg_count('withdrawal_records',$hf)===0,'CSRF mutation');});
pg_case('HTTP withdrawal without an explicit data choice fails before policy',function()use(&$hp,&$hc,&$hs,&$hf,&$he){$r=pg_email_http_request($hp,$hs,$hf,$he,'RETAIN_FOR_ANALYSIS');$r['mode']='';$reply=pf_http($hp['public'],$hc,$r);pe_assert($reply['status']===422&&pg_count('withdrawal_records',$hf)===0,'Confirmation bypass');});
pg_case('HTTP B1 confirmation returns configured withdrawal outcome',function()use(&$hp,&$hc,&$hs,&$hf,&$he){$r=pg_email_http_request($hp,$hs,$hf,$he,'RETAIN_FOR_ANALYSIS');$reply=pf_http($hp['public'],$hc,$r);pe_assert($reply['status']===200&&strpos($reply['data']['html'],'data-notice="withdrawal"')!==false&&pg_row($hf)['data_policy']==='RETAIN_FOR_ANALYSIS',substr($reply['body'],0,400));$hs=$reply;});
pg_case('HTTP lookup of an already withdrawn email is read-only',function()use(&$hp,&$hc,&$hs,&$hf,&$he){$before=pg_row($hf);$r=pe_http_request($hs,'withdrawal_lookup');unset($r['expected_revision']);$r['email']=$he;$reply=pf_http($hp['public'],$hc,$r);pe_assert($reply['status']===200&&isset($reply['data']['withdrawal_check']['revision']),'Email lookup rejected');pe_equal($before,pg_row($hf));});
pg_case('HTTP B1 to B2 confirmation excludes data immediately with pending cleanup',function()use(&$hp,&$hc,&$hs,&$hf,&$hb2,&$he){$r=pg_email_http_request($hp,$hs,$hf,$he,'DO_NOT_USE');$hb2=$r;$reply=pf_http($hp['public'],$hc,$r);$w=(new EIPSI\StudyEngine\Persistence\WithdrawalRepository(pf_db()))->find($hf['access']['execution_id']);pe_assert($reply['status']===200&&pg_export($hf)['rows']===array()&&$w['cleanup_state']==='PENDING',substr($reply['body'],0,400));});
pg_case('HTTP lost-response retry after cleanup returns the existing withdrawal record',function()use(&$hp,&$hc,&$hf,&$hb2){$before=(new EIPSI\StudyEngine\Persistence\WithdrawalRepository(pf_db()))->find($hf['access']['execution_id']);pg_cleanup($hf);$r=pf_http($hp['public'],$hc,$hb2);$after=(new EIPSI\StudyEngine\Persistence\WithdrawalRepository(pf_db()))->find($hf['access']['execution_id']);pe_assert($r['status']===200&&$before['id']===$after['id']&&$after['cleanup_state']==='COMPLETE_LOCAL',substr($r['body'],0,400));});
pg_case('HTTP email withdrawal lookup works from a fresh browser without participant proof',function()use(&$hp,&$he){$entry=pf_http($hp['public']);$r=pe_http_request($entry,'withdrawal_lookup');$r['email']=$he;unset($r['expected_revision']);$reply=pf_http($hp['public'],$entry['cookies'],$r);pe_assert($reply['status']===200&&isset($reply['data']['withdrawal_check']['revision']),'Participant cookie required');});
